// backend/tests/integration/donation.test.ts
// Testes de integração para doações via feed
// FASE 4: Doações via Feed

import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import { v4 as uuidv4 } from 'uuid';
import { pool } from '../../src/core/database/pool';
import { donationService } from '../../src/core/unifybank/donation.service';
import { accountService } from '../../src/core/economy/accounts/account.service';
import { resolveGlobalUserId } from '../../src/core/identity/identity.utils';
import { SocialRepository } from '../../src/modules/social/social.repository';

describe('Donation Service - Integração', () => {
  const testTenantId = uuidv4();
  let testFromUserId: string;
  let testToUserId: string;
  let testFromGlobalUserId: string;
  let testToGlobalUserId: string;
  let testGroupId: string;
  let testProjectId: string;

  beforeAll(async () => {
    // Criar tenant de teste
    await pool.query(
      `INSERT INTO tenants (tenant_id, name, city_id)
       VALUES ($1, 'Test Tenant', NULL)
       ON CONFLICT (tenant_id) DO NOTHING`,
      [testTenantId]
    );

    // Criar usuários de teste
    testFromUserId = uuidv4();
    testToUserId = uuidv4();
    testFromGlobalUserId = uuidv4();
    testToGlobalUserId = uuidv4();

    await pool.query(
      `INSERT INTO global_users (global_user_id, full_name, created_at)
       VALUES ($1, 'Test From User', now()), ($2, 'Test To User', now())
       ON CONFLICT (global_user_id) DO NOTHING`,
      [testFromGlobalUserId, testToGlobalUserId]
    );

    await pool.query(
      `INSERT INTO users (user_id, tenant_id, email, global_user_id, created_at)
       VALUES ($1, $2, 'from@test.com', $3, now()), ($4, $2, 'to@test.com', $5, now())
       ON CONFLICT (user_id) DO NOTHING`,
      [testFromUserId, testTenantId, testFromGlobalUserId, testToUserId, testToGlobalUserId]
    );

    // Criar grupo de teste
    testGroupId = uuidv4();
    await pool.query(
      `INSERT INTO groups (group_id, tenant_id, owner_user_id, name, description, is_active, created_at)
       VALUES ($1, $2, $3, 'Test Group', 'Test Description', true, now())
       ON CONFLICT (group_id) DO NOTHING`,
      [testGroupId, testTenantId, testFromUserId]
    );

    // Criar projeto de teste (post_projects)
    testProjectId = uuidv4();
    const testPostId = uuidv4();
    
    // Criar post primeiro
    await pool.query(
      `INSERT INTO posts (post_id, tenant_id, global_user_id, content, intent, created_at)
       VALUES ($1, $2, $3, 'Test Project Post', 'project', now())
       ON CONFLICT (post_id) DO NOTHING`,
      [testPostId, testTenantId, testFromGlobalUserId]
    );

    // Criar projeto
    await pool.query(
      `INSERT INTO post_projects (project_id, post_id, tenant_id, group_id, status, created_at)
       VALUES ($1, $2, $3, $4, 'active', now())
       ON CONFLICT (project_id) DO NOTHING`,
      [testProjectId, testPostId, testTenantId, testGroupId]
    );

    // Criar contas e adicionar saldo inicial
    const fromAccount = await accountService.getOrCreateUserPrimaryAccount(
      testTenantId,
      testFromUserId,
      'BRL'
    );

    // Adicionar saldo inicial (100 BRL)
    await pool.query(
      `UPDATE accounts SET balance = 100 WHERE account_id = $1`,
      [fromAccount.accountId]
    );
  });

  afterAll(async () => {
    // Limpar dados de teste
    try {
      await pool.query(`DELETE FROM transactions WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM posts WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM post_projects WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM accounts WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM groups WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM users WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM tenants WHERE tenant_id = $1`, [testTenantId]);
    } catch (error) {
      // Ignorar erros de limpeza
    }
  });

  describe('Doação para usuário', () => {
    it('deve criar doação válida para outro usuário', async () => {
      const result = await donationService.createDonation(testTenantId, {
        fromUserId: testFromUserId,
        targetType: 'user',
        targetId: testToUserId,
        amount: 50,
        message: 'Doação de teste',
      });

      expect(result).toBeDefined();
      expect(result.fromUserId).toBe(testFromUserId);
      expect(result.targetType).toBe('user');
      expect(result.targetId).toBe(testToUserId);
      expect(result.amount).toBe(50);
      expect(result.message).toBe('Doação de teste');
      expect(result.transactionId).toBeDefined();
      expect(result.feedPostId).toBeDefined();
    });

    it('deve rejeitar doação para si mesmo', async () => {
      await expect(
        donationService.createDonation(testTenantId, {
          fromUserId: testFromUserId,
          targetType: 'user',
          targetId: testFromUserId,
          amount: 10,
        })
      ).rejects.toThrow('Cannot donate to yourself');
    });

    it('deve rejeitar doação com saldo insuficiente', async () => {
      await expect(
        donationService.createDonation(testTenantId, {
          fromUserId: testFromUserId,
          targetType: 'user',
          targetId: testToUserId,
          amount: 200, // Mais que o saldo disponível
        })
      ).rejects.toThrow('Insufficient balance');
    });

    it('deve rejeitar doação para usuário inexistente', async () => {
      const nonExistentUserId = uuidv4();
      await expect(
        donationService.createDonation(testTenantId, {
          fromUserId: testFromUserId,
          targetType: 'user',
          targetId: nonExistentUserId,
          amount: 10,
        })
      ).rejects.toThrow('not found');
    });
  });

  describe('Doação para grupo', () => {
    it('deve criar doação válida para grupo', async () => {
      const result = await donationService.createDonation(testTenantId, {
        fromUserId: testFromUserId,
        targetType: 'group',
        targetId: testGroupId,
        amount: 20,
        message: 'Doação para grupo',
      });

      expect(result).toBeDefined();
      expect(result.targetType).toBe('group');
      expect(result.targetId).toBe(testGroupId);
      expect(result.amount).toBe(20);
      expect(result.transactionId).toBeDefined();
    });

    it('deve rejeitar doação para grupo inexistente', async () => {
      const nonExistentGroupId = uuidv4();
      await expect(
        donationService.createDonation(testTenantId, {
          fromUserId: testFromUserId,
          targetType: 'group',
          targetId: nonExistentGroupId,
          amount: 10,
        })
      ).rejects.toThrow('not found');
    });
  });

  describe('Doação para projeto', () => {
    it('deve criar doação válida para projeto', async () => {
      const result = await donationService.createDonation(testTenantId, {
        fromUserId: testFromUserId,
        targetType: 'project',
        targetId: testProjectId,
        amount: 15,
        message: 'Doação para projeto',
      });

      expect(result).toBeDefined();
      expect(result.targetType).toBe('project');
      expect(result.targetId).toBe(testProjectId);
      expect(result.amount).toBe(15);
      expect(result.transactionId).toBeDefined();
    });

    it('deve rejeitar doação para projeto inexistente', async () => {
      const nonExistentProjectId = uuidv4();
      await expect(
        donationService.createDonation(testTenantId, {
          fromUserId: testFromUserId,
          targetType: 'project',
          targetId: nonExistentProjectId,
          amount: 10,
        })
      ).rejects.toThrow('not found');
    });
  });

  describe('Idempotência', () => {
    it('deve garantir idempotência com eventId duplicado', async () => {
      const eventId = uuidv4();

      const result1 = await donationService.createDonation(testTenantId, {
        fromUserId: testFromUserId,
        targetType: 'user',
        targetId: testToUserId,
        amount: 5,
        eventId,
      });

      // Segunda chamada com mesmo eventId deve retornar erro de duplicata
      await expect(
        donationService.createDonation(testTenantId, {
          fromUserId: testFromUserId,
          targetType: 'user',
          targetId: testToUserId,
          amount: 5,
          eventId,
        })
      ).rejects.toThrow();
    });
  });

  describe('Feed social', () => {
    it('deve criar evento no feed após doação', async () => {
      const result = await donationService.createDonation(testTenantId, {
        fromUserId: testFromUserId,
        targetType: 'user',
        targetId: testToUserId,
        amount: 10,
        message: 'Mensagem de teste',
      });

      expect(result.feedPostId).toBeDefined();

      // Verificar que post foi criado
      const socialRepository = new SocialRepository();
      const post = await socialRepository.findById(testTenantId, result.feedPostId!);

      expect(post).toBeDefined();
      expect(post?.metadata?.type).toBe('DONATION');
      expect(post?.metadata?.targetType).toBe('user');
      expect(post?.metadata?.targetId).toBe(testToUserId);
      expect(post?.metadata?.amount).toBe(10);
      expect(post?.metadata?.message).toBe('Mensagem de teste');
    });
  });

  describe('Ledger balanceado', () => {
    it('deve manter ledger balanceado após doação', async () => {
      const amount = 25;

      await donationService.createDonation(testTenantId, {
        fromUserId: testFromUserId,
        targetType: 'user',
        targetId: testToUserId,
        amount,
      });

      // Verificar ledger
      const ledgerResult = await pool.query<{ total_debits: string; total_credits: string }>(
        `
        SELECT 
          COALESCE(SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE 0 END), 0)::text as total_debits,
          COALESCE(SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE 0 END), 0)::text as total_credits
        FROM ledger
        WHERE tenant_id = $1
        `,
        [testTenantId]
      );

      const totalDebits = parseFloat(ledgerResult.rows[0]?.total_debits || '0');
      const totalCredits = parseFloat(ledgerResult.rows[0]?.total_credits || '0');

      // Ledger deve estar balanceado (débitos = créditos)
      expect(totalDebits).toBe(totalCredits);
    });
  });

  describe('Rate limit', () => {
    it('deve aplicar limite de 20 doações por dia', async () => {
      // Criar 20 doações (limite)
      for (let i = 0; i < 20; i++) {
        try {
          await donationService.createDonation(testTenantId, {
            fromUserId: testFromUserId,
            targetType: 'user',
            targetId: testToUserId,
            amount: 0.01, // Valor mínimo
            eventId: uuidv4(),
          });
        } catch (error) {
          // Pode falhar por saldo, continuar
        }
      }

      // 21ª doação deve falhar
      await expect(
        donationService.createDonation(testTenantId, {
          fromUserId: testFromUserId,
          targetType: 'user',
          targetId: testToUserId,
          amount: 0.01,
          eventId: uuidv4(),
        })
      ).rejects.toThrow('limit exceeded');
    });
  });
});




























